    {
      "claim": "By shifting from static, check-box procedures to tiered, outcome-focused metrics, we ensure that oversight scales with compute, not with corporate headcount.",
      "targets": [
        "AN-11"
      ]
    },
    {
      "claim": "Treating safety verification as a public utility decouples the technical requirement for safety from the capital-intensive burden of building custom regulatory infrastructure.",
      "targets": [
